// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): English 9, Unit 3, Argument Writing.
// Our own wording and questions, written to the named national standards the course follows: the Common Core State
// Standards for English Language Arts, Writing W.9-10.1a-e (introduce a precise claim and organize reasons and evidence,
// develop claims and counterclaims fairly, link sections with transitions, keep a formal style and objective tone, and end
// with a concluding statement that follows), W.9-10.4 (clear and coherent writing) and W.9-10.5 (plan, revise, edit), with
// Language L.9-10.1a (parallel structure) and L.9-10.2 (semicolons and colons) taught as they serve an argument. Nine outline
// topics. Every paragraph, draft, claim and number is fictional and labelled so; nothing is quoted from any real text.
// A question asks about the words on the page: the answer follows from the printed text or from a standard rule of writing.
// Every question offers lettered choices in its prompt and takes the letter (or the choice's own words); the right letter moves.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional student paragraph';
const PS={
 phones:[FIC,['Schools should allow phones at lunch.','First, lunch is a break, and students use it to talk with family.','Second, in a fictional survey of 120 students, 96 said a phone helps them relax.','Some teachers worry about cheating; however, no tests are given at lunch.','For these reasons, the school should allow phones during lunch.']],
 hw:[FIC,['Homework should be limited to 30 minutes a night.','Long assignments leave students tired, and tired students learn less.','In a fictional study of 90 students, those with under 30 minutes of homework averaged 84 on tests, while those with over 90 minutes averaged 79.','Some parents believe more homework builds discipline; however, short, regular tasks build discipline too.','Because the evidence favors shorter work, the school should adopt a 30-minute limit.']],
 lunch:[FIC,['The cafeteria should serve more fresh fruit.','Fruit gives students energy for afternoon classes.','At the fictional Hill School, 150 of 200 students chose fruit when it was offered at no extra cost.','Critics say fresh fruit costs more than packaged snacks; however, the fictional district paid only 12 cents more per tray.','Therefore the cafeteria should add a fruit bar.']],
 park:[FIC,['The town should build a skate park on the empty lot beside the library.','First, teenagers now skate in the street, which is dangerous.','Second, a fictional town report counted 14 skating injuries on Main Street last year.','Third, a park would give skaters a safe place to practice.','Some neighbors fear noise; however, a fence and a 9 p.m. closing time would limit it.','The town should therefore approve the skate park.']],
 music:['Fictional student draft',['The school board should fund the music program.','Honestly, cutting music is a dumb idea, and you would have to be crazy to support it.','In a fictional survey, 82 of 100 students named music class as their favorite part of the day.','The board should vote to keep the program.']],
 recycle:['Fictional student draft',['Our school should add a recycling program.','Recycling helps the planet.','In a fictional count, the cafeteria threw away 400 plastic bottles in one week.','Others say recycling bins cost too much; however, the fictional district pays only $90 per bin.','A recycling program would keep those bottles out of the trash.']]};
const P=k=>PS[k];
/* [skill, passage, the question, the right choice, two wrong choices, why] */
const ROWS=[
 ['claim',null,'A student must write an argument about school uniforms. Which is the most precise, arguable claim?','Public middle schools should adopt a uniform policy because uniforms reduce morning conflicts over clothing',['School uniforms are something that many people talk about','Some schools in some countries require uniforms'],'A precise claim takes a side that readers could dispute and says why. The other two only name a topic or report a fact.'],
 ['claim',null,'Which of these is a claim that can be argued, not a fact?','The town should build a skate park on the empty lot behind the library',['The empty lot behind the library measures 40 meters by 30 meters (fictional)','The library opens at 9 a.m. on weekdays (fictional)'],'“Should” signals a position that reasonable people could dispute. A measurement and an opening time are facts that can simply be checked.'],
 ['claim',null,'Which claim gives a writer the clearest job in a four-paragraph essay?','Our school should replace paper cups with reusable cups to cut its weekly trash',['Cups are used in many places','Recycling is important'],'It names the action, the place and the benefit, so each paragraph has a task. The others are too general to organize an essay.'],
 ['claim',null,'Which claim is too broad to prove in one short essay?','Technology has changed everything about human life',['The library should let students renew books online','The gym should stay open until 6 p.m. on Fridays'],'“Everything about human life” cannot be covered with a few reasons. The other two are narrow enough to support with a few pieces of evidence.'],
 ['claim',null,'Why is “Water boils at 100 degrees Celsius at sea level” a poor claim for an argument essay?','It is a settled fact, so no reasonable reader would take the other side',['It is too long to prove in one paragraph','It states an opinion that has no evidence'],'An argument needs a claim that someone could dispute. A well-established fact leaves nothing to argue.'],
 ['claim',null,'A draft says “Sports are good.” Which revision is the most precise?','Ninth graders should keep the daily physical education requirement because it builds fitness and teamwork',['Sports are very, very good for everybody','Sports are good in many different ways'],'The revision names who, what and why. Adding “very” or “many ways” makes the sentence louder, not more precise.'],
 ['claim','phones','Which sentence states the writer’s claim?','Schools should allow phones at lunch',['Second, in a fictional survey of 120 students, 96 said a phone helps them relax','Some teachers worry about cheating; however, no tests are given at lunch'],'The first sentence takes the position the rest of the paragraph supports. The others are evidence and a counterclaim.'],
 ['claim','hw','Which phrase makes the claim precise by naming an exact limit?','limited to 30 minutes a night',['leave students tired','builds discipline'],'The number turns a vague wish into a specific policy that readers can accept or reject.'],
 ['claim','lunch','A classmate suggests replacing the claim with “Fruit is good.” Why is the writer’s claim better?','It names an action for the cafeteria that readers could accept or reject',['It is shorter and easier to read','It avoids mentioning the cafeteria'],'“Fruit is good” asks nothing of anyone and nobody would disagree. The writer’s claim proposes something to argue for.'],
 ['claim',null,'Which revision of “Zoos are bad” is the most precise and arguable?','Zoos should close or enlarge the enclosures that keep elephants in small spaces',['Zoos are very, very bad for every animal','Many people have opinions about zoos'],'It limits the claim to one practice and one kind of animal, and it says what should be done. The others are vague or only describe opinions.'],
 ['organize',null,'Fictional jumbled paragraph. 1: Therefore the library should open on Sundays. 2: Many students work on weekdays and cannot reach the library before it closes at 5 p.m. 3: The library should open on Sundays. 4: In a fictional count, 140 students used the Saturday hours last month. Which order of the sentences is best: claim, reason, evidence, conclusion?','3-2-4-1',['1-3-2-4','2-4-3-1'],'Sentence 3 is the claim, 2 is the reason, 4 is the evidence, and 1 begins with “Therefore,” so it is the conclusion.'],
 ['organize',null,'Fictional jumbled paragraph. 1: Some residents fear that the extra noise will bother neighbors, but the garden would close at 9 p.m. 2: The town should build a community garden on Oak Street. 3: The garden would give families fresh food at low cost. 4: For these reasons, the council should approve the garden. Which order puts the claim first, the reason next, the counterclaim with its answer after that, and the conclusion last?','2-3-1-4',['2-1-3-4','3-2-4-1'],'Sentence 2 is the claim, 3 the reason, 1 the counterclaim with its answer, and 4 the conclusion drawn from “these reasons.”'],
 ['organize',null,'Fictional jumbled paragraph. 1: A fictional survey found that 70 of 100 neighbors would use the pool each week. 2: Building a public pool would give the neighborhood a safe place to exercise. 3: The city should build a public pool on Cedar Road. 4: Thus the council should vote yes. Which order places the claim, then the reason, then its evidence, then the conclusion?','3-2-1-4',['2-3-1-4','3-1-2-4'],'The claim (3) comes first, the reason (2) explains why, the survey (1) is evidence for the reason, and “Thus” (4) draws the conclusion.'],
 ['organize','park','Counting the sentences that begin First, Second or Third, how many reasons does the writer give for the claim?','Three',['Two','Four'],'The paragraph has a First, a Second and a Third reason, so three. The claim and the counterclaim do not begin that way.'],
 ['organize',null,'Which outline shows clear relationships among claim, reasons, evidence and counterclaim?','Claim; each reason followed by its own evidence; counterclaim with rebuttal; conclusion',['Claim; all the evidence in one pile; every reason at the end; no conclusion','Counterclaim; conclusion; claim; evidence; reasons'],'Pairing each reason with its evidence shows the reader how they relate. The others scatter the parts or put the conclusion in the wrong place.'],
 ['organize','hw','In this paragraph, what is the sentence beginning “In a fictional study” doing?','It gives evidence that students with less homework scored higher',['It states the opposing view held by parents','It draws the conclusion of the paragraph'],'The two group averages, 84 and 79, back up the reason that long assignments make students learn less.'],
 ['organize','lunch','Which sentence presents the opposing view?','Critics say fresh fruit costs more than packaged snacks; however, the fictional district paid only 12 cents more per tray',['Fruit gives students energy for afternoon classes','Therefore the cafeteria should add a fruit bar'],'“Critics say” introduces the other side. The other sentences are a reason and the conclusion.'],
 ['organize',null,'Which statement describes one common way to order reasons?','In order of importance, building toward the strongest reason',['In the order the writer happened to think of them','By the alphabetical order of each reason’s first word'],'Writers choose an order on purpose. Importance is a common plan; random or alphabetical order does not help the reader follow the argument.'],
 ['organize',null,'A paragraph argues for adding a fruit bar to the cafeteria. Which sentence does not belong in it?','The cafeteria floor was repainted blue last spring.',['Fruit gives students energy for afternoon classes.','A fruit bar would cost the district only a few cents per tray.'],'The paint color has nothing to do with the claim. A paragraph is unified when every sentence supports its point.'],
 ['organize',null,'Which topic sentence best opens a body paragraph about cost?','The most practical reason to adopt the plan is its low cost.',['There are many things to say about this subject.','Cost is a word with several meanings.'],'A topic sentence names the point of the paragraph. The others do not say what the paragraph will prove.'],
 ['evidence',null,'Reason: “Late nights lower test scores.” Which evidence supports it best?','In a fictional survey of 60 students, those who slept under 6 hours averaged 78 on tests and those who slept 8 hours averaged 88',['The writer’s cousin goes to bed late and loves pizza','Everyone knows that sleep matters a great deal'],'Matched figures compare sleep with scores. A cousin’s habits and a general remark do not test the reason.'],
 ['evidence',null,'Reason: “A bike lane would make Pine Street safer.” Which evidence is relevant to that reason?','On the fictional Elm Street, crashes fell from 18 to 7 after a bike lane opened',['Pine Street was named after a pine tree that once stood there','Bike helmets come in many colors'],'Falling crash counts bear directly on safety. A street’s name and helmet colors say nothing about safety.'],
 ['evidence',null,'“Dr. Lee, a fictional pediatrician, says children need fruit every day.” Which kind of evidence is this?','Expert testimony',['A statistic','A personal anecdote'],'A named specialist’s statement is testimony from an authority. It has no data and is not one person’s own story.'],
 ['evidence',null,'“Last year my aunt walked to work and lost five pounds.” Which kind of evidence is this, and how strong is it?','An anecdote, which is weak because one case does not prove a general claim',['A statistic, which is strong because it has a number','Expert testimony, which is strong because aunts know best'],'A single personal story is an anecdote. It can illustrate a point but cannot prove a claim about everyone.'],
 ['evidence',null,'A writer’s only evidence for a claim about a whole school is the opinion of one friend. What is the problem?','The evidence is insufficient: one voice cannot represent the whole school',['The evidence is irrelevant because friends never know anything','The evidence is too long to read'],'Sufficient evidence is enough of it. One opinion is too little to support a claim about a whole school.'],
 ['evidence',null,'Reason: “School gardens teach science.” Which sentence is not relevant evidence for that reason?','The garden’s wooden boxes were painted green',['Students measured plant growth each week and recorded the data','Science scores rose after the garden project (fictional)'],'Paint color does not show that anyone learned science. Measuring and recording data, and rising scores, do.'],
 ['evidence','phones','In the survey, what percent of the 120 students said a phone helps them relax?','80 percent',['96 percent','20 percent'],'96 out of 120 is 96 ÷ 120 = 0.8, which is 80 percent. The number 96 is a count, and 20 percent is the share who did not say so.'],
 ['evidence','lunch','What percent of the 200 students chose fruit?','75 percent',['150 percent','25 percent'],'150 ÷ 200 = 0.75, which is 75 percent. A share of the students cannot be 150 percent, and 25 percent is those who did not choose fruit.'],
 ['evidence','hw','By how many points did the group with under 30 minutes of homework outscore the group with over 90 minutes?','5 points',['84 points','163 points'],'The averages were 84 and 79, and 84 − 79 = 5. Adding them gives 163, and 84 is only one average.'],
 ['evidence',null,'After a writer gives the 5-point test gap between two homework groups, which sentence best explains how the statistic supports shorter homework?','The gap shows that students with less homework did better, which supports shorter assignments',['The statistic appears in the second paragraph of the essay','Many students have homework every night'],'Evidence needs commentary that links it to the reason. The other sentences only locate it or restate a general fact.'],
 ['rebut',null,'Which sentence states an opposing view fairly?','Some parents worry that free time online will crowd out conversation at lunch',['Only lazy people could possibly disagree','The other side has no reasons at all'],'A fair statement gives the other side’s real concern. Insults and “no reasons” misrepresent it.'],
 ['rebut',null,'A writer claims phones should be allowed at lunch. An opponent says phones distract students. Which rebuttal answers that point best?','Lunch is not class time, and the rule would still keep phones silent during lessons',['Phones are used by many people','Opponents are simply wrong and should be ignored'],'The rebuttal meets the distraction worry with a specific answer. The others change the subject or dismiss the opponent.'],
 ['rebut','phones','What does the writer do right after naming the teachers’ worry about cheating?','Answers it by pointing out that no tests are given at lunch',['Repeats the claim in the same words','Moves on to a new topic'],'The word “however” turns from the worry to a reply: cheating needs a test, and lunch has none.'],
 ['rebut','hw','How many sentences in this paragraph present an opposing view?','One',['Two','Three'],'Only the sentence that begins “Some parents believe” gives the other side. It is also where the writer answers it.'],
 ['rebut','lunch','Which detail answers the critics’ worry about cost?','The district paid only 12 cents more per tray',['150 of 200 students chose fruit','Fruit gives students energy for afternoon classes'],'The critics said fruit costs more. The 12-cent figure shows how small the extra cost is.'],
 ['rebut',null,'Why does an argument include a counterclaim?','It shows the writer has considered other views fairly and can answer them',['It proves the opposing view is correct','It lets the writer avoid giving evidence'],'Addressing the other side builds trust. Evidence is still needed for the writer’s own claim.'],
 ['rebut',null,'Which response to the claim “Homework builds discipline” is a rebuttal rather than a dismissal?','Daily 30-minute tasks can build discipline without long hours that leave students tired',['That claim is silly','Nobody has ever said that'],'A rebuttal answers the point with a reason. Mockery and denial give the reader nothing to weigh.'],
 ['rebut',null,'Which phrase best introduces a concession before a rebuttal?','It is true that some neighbors fear noise, but',['Everyone knows neighbors are wrong, and','Noise is, therefore'],'A concession grants part of the opposing view fairly, and then “but” turns to the answer.'],
 ['rebut','park','What solution does the writer offer to the neighbors’ concern about noise?','A fence and a 9 p.m. closing time',['A larger lot','A ban on skateboards'],'The writer answers the worry with two limits on noise. A ban would defeat the claim itself.'],
 ['rebut',null,'A writer ignores every opposing view. What is the likely effect on readers?','Readers may think the writer has not considered the issue fairly',['Readers will find the argument stronger because it is shorter','Readers will agree because no one disagrees'],'Skipping the other side can make an argument look one-sided. Fair writers name and answer it.'],
 ['trans',null,'“Many students ride the bus. ___, others walk to school.” Which transition fits best?','In contrast',['For example','As a result'],'The two sentences set different groups side by side, which is a contrast. The second is not an example or an effect of the first.'],
 ['trans',null,'“The plan is cheap. ___, it is fast.” Which transition adds a second advantage?','In addition',['However','Nevertheless'],'Both sentences praise the plan, so the writer is adding a point. However and nevertheless signal contrast.'],
 ['trans',null,'“Crashes fell from 18 to 7. ___, the council voted to keep the bike lane.” Which transition shows a result?','As a result',['On the other hand','For instance'],'The vote follows from the drop in crashes. “On the other hand” would contrast, and “for instance” would introduce an example.'],
 ['trans',null,'“Some foods are healthy. ___, fresh fruit has fiber and vitamins.” Which transition introduces an example?','For instance',['Nevertheless','Meanwhile'],'Fruit is an example of a healthy food. Nevertheless contrasts, and meanwhile refers to time.'],
 ['trans',null,'Which sentence best opens the paragraph that answers critics, linking it to the reasons before it?','Although these reasons are strong, critics raise a fair concern',['Moving on to a totally different subject','Finally the end has come'],'It refers back to the reasons and then turns to the opposition. The others do not connect the paragraphs.'],
 ['trans',null,'Which transition signals concession, a point granted before the writer’s answer?','Admittedly',['Moreover','Consequently'],'Admittedly grants a point. Moreover adds one and consequently shows a result.'],
 ['trans','phones','What relationship does “however” signal in this paragraph?','Contrast: the writer turns from the teachers’ worry to an answer',['Cause: the worry caused the rule','Example: the worry is one instance of the claim'],'However marks a turn. The sentence admits a worry and then answers it.'],
 ['trans','phones','What does “For these reasons” signal at the start of the last sentence?','A conclusion drawn from the reasons above',['A new reason','A counterclaim'],'The phrase points back at the reasons already given and draws a conclusion from them.'],
 ['trans','park','What do “First,” “Second,” and “Third,” show in the paragraph?','The order of the reasons',['A contrast between reasons','A cause-and-effect chain'],'Ordinal transitions number the reasons so the reader can follow them. They do not make the reasons oppose or cause each other.'],
 ['trans',null,'Which transition shows the writer adding to the earlier point, not contrasting with it?','Furthermore',['Nevertheless','On the contrary'],'Furthermore adds another point in the same direction. The other two turn against what came before.'],
 ['tone',null,'Which revision of “Principal Ames is totally clueless about phones” is the most formal and objective?','The principal’s phone rule does not account for how students use their breaks',['The principal is kind of wrong about phones','Honestly, the principal’s phone rule is dumb'],'It criticizes the rule, not the person, in plain formal words. The others use slang, insults and vague hedging.'],
 ['tone','music','Which sentence breaks the formal style of the draft?','Honestly, cutting music is a dumb idea, and you would have to be crazy to support it',['In a fictional survey, 82 of 100 students named music class as their favorite part of the day','The board should vote to keep the program'],'“Honestly,” “dumb,” and the insult to opponents are informal and subjective. The other sentences are measured.'],
 ['tone','music','Which revision of the second sentence keeps an objective tone?','Cutting music would remove a class that many students value',['Cutting music would be a terrible mistake that only a fool would make','Anyone who disagrees is clearly not thinking'],'It states a consequence without name-calling. The others attack the opponents.'],
 ['tone',null,'Which sentence uses loaded language that undercuts an objective tone?','The greedy board hoards money while students suffer',['The board holds a surplus of $40,000 (fictional)','The board has not yet funded the program'],'“Greedy,” “hoards” and “suffer” are charged words. The others report facts.'],
 ['tone',null,'In a formal argument, which opening is generally preferred?','The school should adopt a later start time',['I personally think maybe the school should adopt a later start time','Okay, so, like, the school needs a later start time'],'A direct, formal claim reads as confident. Hedging and filler weaken the claim and the tone.'],
 ['tone',null,'Which sentence avoids slang and contractions, as formal style usually does?','Many students do not have a quiet place to study',['Lots of kids don’t have a chill spot to study','Tons o’ students can’t find a quiet place'],'Formal writing normally spells out “do not” and avoids slang such as “chill spot.”'],
 ['tone',null,'Which sentence addresses the reader in a formal, third-person way?','Students benefit from a quiet study space',['You know you would study better with a quiet space','Hey reader, just picture a quiet space'],'Formal argument usually talks about people in the third person. Direct address and chatty openers shift the tone.'],
 ['tone',null,'Which sentence states a claim with fitting certainty, without exaggeration?','Shorter assignments will probably improve sleep for many students',['Shorter assignments will fix every problem in every school forever','Shorter assignments might possibly maybe help some tiny bit'],'“Probably” and “many” match what evidence can show. The other two overstate or shrink the claim.'],
 ['tone',null,'Which sentence is an objective statement of fact rather than an emotional appeal?','The fictional district spends $12,000 a year on field trips',['It would be heartbreaking to see children miss field trips','Field trips are the best part of every child’s life'],'A figure can be checked. “Heartbreaking” and “the best part of every child’s life” are feelings.'],
 ['tone','music','How many sentences in the draft contain a number?','One',['Two','Four'],'Only the survey sentence has numbers (82 and 100). Objective evidence often looks like this.'],
 ['end',null,'A paragraph argues that a town should add bike lanes because crashes fell from 18 to 7 in a fictional trial. Which concluding sentence follows from the argument?','With crashes down from 18 to 7 in the trial, the town should add bike lanes citywide',['Bicycles were invented in the nineteenth century, and many people enjoy riding them','In conclusion, opinions differ, so nobody can be sure about anything'],'A conclusion follows from the evidence given. The others wander to an unrelated fact or give up on the claim.'],
 ['end',null,'An essay argued for a 30-minute homework limit. Which final sentence adds a brand-new argument, which a conclusion should avoid?','Also, the school should repaint its hallways green.',['For these reasons, the board should adopt the limit.','Given the evidence, a shorter limit would help students.'],'A conclusion wraps up the argument already made. Hallway paint is a new, unrelated claim.'],
 ['end','hw','What does the last sentence do?','Tells what should be done because of the evidence',['Introduces a new claim','Answers a counterclaim'],'“Because the evidence favors shorter work” links it to the study, and “the school should adopt” states the result.'],
 ['end','phones','The last sentence begins “For these reasons.” What does it restate?','The claim that the school should allow phones at lunch',['The teachers’ worry about cheating','The survey result of 96 of 120'],'The conclusion returns to the claim of the first sentence, in fresh words.'],
 ['end',null,'Which statement describes a strong concluding statement?','It restates the claim in fresh words and says what should follow',['It repeats the first sentence exactly and adds nothing','It apologizes for the argument and invites readers to ignore it'],'A strong conclusion follows from the argument and tells readers what it means. Copying or apologizing does neither.'],
 ['end',null,'A writer argues for a fruit bar. Which conclusion contradicts the argument?','The cafeteria should therefore remove all fresh fruit',['The cafeteria should therefore add a fruit bar','Given students’ choices, the cafeteria should expand its fruit offerings'],'A conclusion must follow from the claim. Removing fruit reverses the argument.'],
 ['end','hw','Which version of the last sentence would not follow from the paragraph?','Because the evidence favors shorter work, the school should assign two hours a night',['Because the evidence favors shorter work, the school should adopt a 30-minute limit','Given these test scores, the school should limit nightly homework'],'The study favors shorter homework, so assigning two hours contradicts it.'],
 ['end',null,'Which closing sentence ends with a call to action that follows from an argument for a fruit bar?','The board should add a fruit bar at the start of the next school year',['Fruit is yellow, red and green in color','The weather was warm on the day of the survey'],'A call to action says what to do. The others are details that lead nowhere.'],
 ['end',null,'In a fictional trial, crashes fell from 18 to 7. A conclusion begins “Because crashes fell by more than half,”. Which ending fits?','the council should keep the bike lane',['the council should remove the bike lane','the weather will be warm next week'],'A drop from 18 to 7 is a fall of about 61 percent, more than half. Keeping the lane follows; removing it or discussing the weather does not.'],
 ['end',null,'Where is the concluding statement best placed?','At the end, after the reasons and the answer to the counterclaim',['Before the claim','Between the claim and the first reason'],'A conclusion draws everything together, so it comes last.'],
 ['clear',null,'A student writes to the school board. Which opening suits that audience and purpose?','Members of the board, I am writing to ask that you adopt a later start time',['Hey guys, what’s up with the early start','Dear Whoever, this is just my random thought about school'],'The first opening is respectful, clear and states the request. The others are casual or vague.'],
 ['clear',null,'Which sentence is the clearest and most concise?','The library should extend its hours',['The library should, in my opinion, kind of extend its hours at this point in time','What the library should do is that it should extend its hours'],'The other two add filler words without adding meaning.'],
 ['clear',null,'Which sentence avoids an unclear pronoun?','Ana told Beth, “Your essay is ready.”',['Ana told Beth that she was ready','Ana told Beth that it was ready'],'“She” could mean Ana or Beth, and “it” has no clear referent. Direct quotation removes the doubt.'],
 ['clear',null,'Which sentence removes the redundancy from “The reason why the plan failed is because it cost too much”?','The plan failed because it cost too much',['The reason why the plan failed is because it cost too much money','The plan failed, and the reason is the cost, because it cost too much'],'“Reason why” and “is because” say the same thing twice. The shortest version says it once.'],
 ['clear',null,'A writer’s task is to argue, not to describe. Which sentence belongs in the essay?','The district should fund the program because it raises attendance',['The program is held on Tuesdays in the gym','The gym has a wooden floor and tall windows'],'An argument essay needs sentences that support a claim. Schedules and room descriptions do not.'],
 ['clear',null,'Which word best completes “The new rule will ___ student stress” in precise, formal writing?','reduce',['do something to','mess with'],'“Reduce” says exactly what is expected. The others are vague or slangy.'],
 ['clear','hw','What makes this paragraph coherent, so its sentences hold together?','Each sentence connects to the claim about a 30-minute limit',['Every sentence has the same length','Every sentence begins with the same word'],'Coherence means the parts relate to one controlling idea. Matching length or openings does not make an argument hang together.'],
 ['clear','park','Count the sentences in the paragraph: how many are there?','Six',['Five','Seven'],'The claim, three reasons, the counterclaim and the conclusion make six sentences.'],
 ['clear',null,'Which version of the sentence is a complete, clear statement?','Because the park is safe, families will use it',['Because the park is safe.','The park, which is safe and clean and near the library'],'The first has a subject and a verb in the main clause. The others are fragments.'],
 ['clear',null,'An argument essay is for ninth-grade classmates. Which sentence suits that audience while staying formal?','Students often study better in a quiet room',['Pupils of the present generation endeavor to study more efficaciously in tranquil chambers','Kids study awesome in a quiet room'],'Plain, correct wording fits the audience. The second is overblown, and the third is slangy.'],
 ['revise',null,'Which task is revising, not editing?','Adding evidence to a reason that has none, and moving a paragraph',['Correcting a misspelled word','Adding a missing comma'],'Revising changes ideas, evidence and order. Spelling and commas are editing.'],
 ['revise',null,'Which task is editing?','Fixing a comma splice and a misspelled word',['Rewriting the claim','Adding a new body paragraph'],'Editing corrects conventions. New claims and paragraphs belong to revising.'],
 ['revise',null,'Which step belongs to planning before drafting?','Listing the reasons and matching evidence to each',['Proofreading the final copy','Publishing the essay'],'Planning happens first. Proofreading and publishing come last.'],
 ['revise','recycle','Which sentence gives a reason without evidence and so needs revising?','Recycling helps the planet',['In a fictional count, the cafeteria threw away 400 plastic bottles in one week','Others say recycling bins cost too much; however, the fictional district pays only $90 per bin'],'The sentence states a general reason but offers no figure or example to back it.'],
 ['revise','recycle','How many sentences does the draft have?','Five',['Four','Six'],'The claim, the reason, the count of bottles, the counterclaim with answer and the last sentence make five.'],
 ['revise','recycle','A peer says the last sentence does not tie to the evidence. Which revised ending helps most?','Keeping 400 bottles a week out of the trash would shrink the cafeteria’s waste, so the school should start the program',['Recycling is good','Bottles are made of plastic'],'It uses the evidence and draws a conclusion from it. The others are general or off the point.'],
 ['revise',null,'A peer reader writes, “Paragraph 3 makes a claim but gives no evidence.” What is the best revision?','Add a statistic, an example or testimony that supports the claim',['Delete the claim','Add more adjectives to the claim'],'The problem is missing support, so the writer adds evidence. Adjectives do not prove anything.'],
 ['revise',null,'Why is reading a draft aloud useful in editing?','It helps writers hear awkward phrasing and missing words',['It replaces the need to revise','It proves the argument is correct'],'The ear catches what the eye skips. It cannot test an argument’s logic.'],
 ['revise',null,'The order of the writing process is commonly taught as which sequence?','Plan, draft, revise, edit, publish',['Publish, draft, plan, edit, revise','Edit, publish, plan, draft, revise'],'Writers plan first, then draft, then improve ideas, then correct, then share.'],
 ['revise',null,'A writer adds a paragraph that answers an opposing view. Is that planning, revising or editing?','Revising, because it changes the content and organization',['Editing, because it adds words','Planning, because it happens before any draft exists'],'Adding a paragraph changes ideas and structure of an existing draft, which is revising.'],
 ['parallel',null,'Which sentence about after-school clubs uses parallel structure?','Students enjoy reading, writing and debating',['Students enjoy reading, to write and debating','Students enjoy reading, writing and to debate'],'All three items are -ing forms. The others mix an -ing form with to-forms.'],
 ['parallel',null,'Which sentence about the city council uses parallel structure?','The council aims to cut costs, to protect parks and to improve roads',['The council aims to cut costs, protecting parks and the improvement of roads','The council aims to cut costs, to protect parks and improving roads'],'Every item begins with “to” plus a verb. In the others, one or two items change form.'],
 ['parallel',null,'Which version of the sentence about a good essay is parallel?','A good essay is clear, logical and persuasive',['A good essay is clear, has logic and persuasion','A good essay is clear, logical and it persuades readers'],'Three adjectives match. The others swap in a verb phrase or a noun.'],
 ['parallel',null,'Which sentence about savings is parallel?','The plan will not only save money but also improve safety',['The plan will not only save money but also safety will improve','The plan will not only save money but improvement of safety'],'After “not only” and “but also,” both parts need the same form: save money, improve safety.'],
 ['parallel',null,'Which sentence about voters is parallel?','Voters want leaders who listen, who act and who explain',['Voters want leaders who listen, acting and who explain','Voters want leaders who listen, who act and explanations'],'Each item is a “who” clause. The others break the pattern with -ing or a noun.'],
 ['parallel',null,'Which sentence about a school report is parallel?','The report recommends hiring two tutors, extending library hours and buying new books',['The report recommends hiring two tutors, to extend library hours and buying new books','The report recommends hiring two tutors, the extension of library hours and buying new books'],'All three recommendations are -ing phrases. The others slip in a to-phrase or a noun phrase.'],
 ['parallel',null,'Which sentence about a meeting is parallel?','They agreed to meet on Monday and to vote on Tuesday',['They agreed to meet on Monday and voting on Tuesday','They agreed to meet on Monday and that they would vote on Tuesday'],'Both actions are “to” plus a verb. The others change the form of the second.'],
 ['parallel',null,'Which sentence about practice fixes the faulty parallelism in “The coach told us to stretch, hydrate and that we should sleep early”?','The coach told us to stretch, to hydrate and to sleep early',['The coach told us to stretch, hydrate and that sleeping early was good','The coach told us stretching, to hydrate and sleep early'],'Making all three items “to” plus a verb matches them.'],
 ['parallel',null,'What does parallel structure mean?','Matching grammatical form for items that do the same job',['Repeating the same word in every sentence','Using sentences of exactly the same length'],'Parallelism is about matching forms in a list or pair, not repeating words or counting syllables.'],
 ['parallel',null,'Why does parallel structure help an argument?','It makes ideas easier to follow and gives the writing rhythm and balance',['It lets the writer skip evidence','It makes every sentence the same length'],'Matching forms signal that ideas are equal in importance, which helps readers follow them.'],
 ['semi',null,'Which choice corrects the comma splice in “The vote was close, the mayor won” with a semicolon?','The vote was close; the mayor won',['The vote was close, the mayor won','The vote was close; and, the mayor won'],'Two complete clauses need a semicolon (or a comma plus a conjunction). A bare comma is a splice.'],
 ['semi',null,'Which choice corrects the comma splice in “The library closes at five, students must leave by then” with a semicolon?','The library closes at five; students must leave by then',['The library closes at five, students must leave by then','The library closes at five students must leave by then'],'A semicolon can join two related independent clauses. Without punctuation the sentence runs on.'],
 ['semi',null,'Which choice corrects the comma splice in “Rain fell all afternoon, the game went on anyway” with a semicolon?','Rain fell all afternoon; the game went on anyway',['Rain fell all afternoon, the game went on anyway','Rain fell all afternoon the game went on anyway'],'The semicolon takes the place of the weak comma between two complete thoughts.'],
 ['semi',null,'Which choice corrects the comma splice in “The essay was late, the teacher still read it” with a semicolon?','The essay was late; the teacher still read it',['The essay was late, the teacher still read it','The essay was late the teacher still read it'],'Both halves could stand alone, so a semicolon joins them.'],
 ['semi',null,'Which choice corrects the comma splice in “Voters waited in line, the polls stayed open” with a semicolon?','Voters waited in line; the polls stayed open',['Voters waited in line, the polls stayed open','Voters waited in line the polls stayed open'],'A comma alone cannot join two independent clauses; a semicolon can.'],
 ['semi',null,'Which sentence is punctuated correctly?','The plan is cheap; however, it is also fast',['The plan is cheap, however it is also fast','The plan is cheap; however it is also fast'],'A conjunctive adverb such as “however” between two clauses takes a semicolon before it and a comma after it.'],
 ['semi',null,'Which sentence correctly joins two related clauses with a semicolon and a conjunctive adverb?','The trial ended early; consequently, the data were limited',['The trial ended early, consequently, the data were limited','The trial ended early; consequently the data, were limited'],'The semicolon comes before the adverb, and a comma follows it. The comma splice and the misplaced comma are errors.'],
 ['semi',null,'Which sentence uses a colon correctly to introduce a list?','The club needs three things: a room, a budget and a leader',['The club needs: a room, a budget and a leader','The club needs three things, a room, a budget and a leader'],'A colon follows a complete clause. “The club needs” is not complete, and the comma version is a splice.'],
 ['semi',null,'Which sentence introduces a quotation with a colon after a complete clause?','The sign made its point clearly: “Quiet, exams in progress.”',['The sign was: “Quiet, exams in progress.”','The sign made its point clearly; “Quiet, exams in progress.”'],'The words before the colon form a complete clause. A colon after “was” interrupts the sentence, and a semicolon does not introduce a quotation.'],
 ['semi',null,'When is a semicolon not correct?','Between a main clause and a fragment such as “because it rained”',['Between two closely related main clauses','Before a conjunctive adverb that joins two main clauses'],'A semicolon links independent clauses. A fragment cannot stand alone.'],
 ['semi',null,'Which sentence uses semicolons correctly in a series whose items already contain commas?','The team visited Austin, Texas; Reno, Nevada; and Salem, Oregon',['The team visited Austin, Texas, Reno, Nevada, and Salem, Oregon','The team visited Austin; Texas; Reno; Nevada; and Salem; Oregon'],'Semicolons separate items that contain commas. Commas alone blur the items, and semicolons everywhere split each city from its state.'],
 ['semi',null,'Which choice best describes a comma splice?','Two main clauses joined by only a comma',['A list with too many commas','A comma placed after an introductory word'],'A comma splice joins independent clauses with a comma and no conjunction.']];
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Fictional claims for an essay about lunch. Which is the strongest, most precise claim? A: Schools have lunch periods, B: The school should add ten minutes to lunch because students rush their meals, C: Lunch is good. Answer A, B or C.',
 'Fictional sentences: “The pool is cheap to run. ___, it is close to most homes.” Which transition adds a second reason? A: However, B: In addition, C: Instead. Answer A, B or C.',
 'Fictional sentence: “The bus was late, the bell had already rung.” Which choice fixes the comma splice? A: The bus was late; the bell had already rung, B: The bus was late the bell had already rung, C: The bus was late, and; the bell had already rung. Answer A, B or C.'];
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
export default {
id:'language-h-english-9-argument-writing',subject:'language',level:5,grade:9,standard:'CCSS ELA Writing W.9-10.1a-e, W.9-10.4 and W.9-10.5, and Language L.9-10.1a and L.9-10.2',
title:'Argument Writing',
goal:'Write a fair, well-built argument: choose a precise claim, organize reasons and evidence, match each piece of evidence to its reason, answer the opposing view, link sections with transitions, keep a formal tone, end with a conclusion that follows, and revise and edit with parallel structure, semicolons and colons.',
points:20,
skills:{claim:'Precise claims',organize:'Organizing an argument',evidence:'Matching evidence to reasons',rebut:'Counterclaims and rebuttals',trans:'Transitions',tone:'Formal style and tone',end:'Concluding statements',clear:'Clear, coherent writing',revise:'Planning, revising and editing',parallel:'Parallel structure',semi:'Semicolons and colons'},
outline:[['W.9-10.1a','Introduce precise claims, distinguish them from opposing claims, and organize reasons and evidence',['claim','organize']],['W.9-10.1b','Develop claims and counterclaims fairly, supplying evidence for each',['evidence','rebut']],['W.9-10.1c','Use words, phrases and clauses to link the major sections of the text',['trans']],['W.9-10.1d','Establish and maintain a formal style and objective tone',['tone']],['W.9-10.1e','Provide a concluding statement that follows from the argument',['end']],['W.9-10.4','Produce clear and coherent writing suited to task, purpose and audience',['clear']],['W.9-10.5','Plan, revise, edit and rewrite',['revise']],['L.9-10.1a','Use parallel structure',['parallel']],['L.9-10.2','Use a semicolon to link independent clauses and a colon to introduce a list or quotation',['semi']]],
steps:[
 {skill:'claim',say:'An argument begins with a claim, a position that a reasonable reader could dispute. A fact only reports, and a topic only names a subject. A precise claim says who should do what, and a because-reason makes it sharper. Narrow claims are easier to prove than broad ones.',pic:board('From topic to precise claim',['Topic: school uniforms','Fact: “Some schools require uniforms.”','Claim: “Our school should adopt uniforms.”','Precise: add the reason with because'],['a subject, not a position','true, but nothing to argue','a position readers can dispute','who, what and why']),
  check:{prompt:tryIt(TRY[0]),answer:'B',options:['A','B','C'],hint:'A strong claim takes a side and says why. Which choice proposes something and gives a reason?',pic:pass('Fictional claims',['A: Schools have lunch periods.','B: The school should add ten minutes to lunch because students rush their meals.','C: Lunch is good.'],false)}},
 {skill:'organize',say:'A clear argument has a pattern: the claim, then each reason with its own evidence, then the opposing view with an answer, then a conclusion. Matching each piece of evidence to the reason it supports lets the reader see how the parts relate, instead of facing a pile of facts.',pic:flow('The shape of an argument',[['Claim','Said first and plainly'],['Reasons','Each with its evidence'],['Answer and end','Rebut, then conclude']])},
 {skill:'organize',say:'Read a model paragraph for its jobs. The first sentence is the claim, the second is a reason, the third is evidence for that reason, the fourth admits an opposing view and answers it, and the last draws a conclusion. Ask of each sentence which job it does, and where a sentence does none, cut or move it.',pic:pass('Fictional student paragraph, in order',['The town should paint a crosswalk at Birch Street.','Children cross there on the way to school, and cars rarely stop.','In a fictional count, 60 children crossed Birch Street each morning.','Some drivers say it will slow traffic; however, it adds seconds.','A crosswalk would protect children, so the town should build it.'],false)},
 {skill:'evidence',say:'Evidence must be relevant to its reason and enough to persuade. Statistics, examples and expert testimony can all work, while one personal anecdote cannot prove a general claim. When a number is given, check it: a share is the part divided by the whole, so 30 of 100 students is 30 percent. Then add a sentence that explains how the evidence supports the reason.',pic:{t:'chart',kind:'bars',title:'Fictional: how 100 students get to school',bars:[{label:'Bus',value:45},{label:'Bike',value:30},{label:'Walk',value:25}],suffix:' of 100'}},
 {skill:'rebut',say:'A counterclaim is the strongest reason someone could give for the other side. State it fairly, with no sneering, and then answer it with a rebuttal. A concession grants what is true in the other view before the answer. This shows the writer has weighed the issue and gives readers a reason to trust the claim.',pic:board('Concede, then answer',['Counterclaim: “A bike lane removes parking.”','Concession: It is true that some spaces would go.','Rebuttal: Only 12 of 400 spaces (fictional).','Result: the cost is small next to the benefit'],['the other side','grants a fair point','a reason','the claim stands'])},
 {skill:'trans',say:'Transitions link sentences and sections and tell the reader the relationship. In addition and furthermore add a point, however and in contrast set up a difference, as a result and therefore show a result, for instance gives an example, and finally closes. Choose the transition that matches how the two ideas relate, not one that merely sounds formal.',pic:tab('Transitions by job',[['in addition, furthermore','adds a point'],['however, in contrast','turns to a difference'],['as a result, therefore','shows a result'],['for instance','introduces an example'],['finally, in conclusion','closes the argument']],['Job']),
  check:{prompt:tryIt(TRY[1]),answer:'B',options:['A','B','C'],hint:'Both sentences praise the pool. Which transition adds a second point in the same direction?',pic:pass('Fictional sentences',['The pool is cheap to run.','___, it is close to most homes.'],false)}},
 {skill:'tone',say:'Formal style suits an argument. Use precise words, avoid slang, contractions and insults, and keep a steady, objective tone. State the claim with the certainty the evidence allows: probably is better than always when the proof is partial. Attack ideas, never people, because loaded words make a writer look less fair.',pic:board('Informal to formal',['Informal: “Kids are way too stressed.”','Formal: “Many students report high stress.”','Avoid: slang, “you,” insults, exaggeration','Keep: precise words and a steady tone'],['chatty and vague','measured and specific','what weakens trust','what builds it'])},
 {skill:'end',say:'The concluding statement follows from the argument. It restates the claim in fresh words, says what the evidence means, and may call for action. It does not bring in a new main argument or abandon the claim. A good test is whether the last sentence could not have been written without the paragraphs before it.',pic:flow('A conclusion that follows',[['Restate','The claim, new words'],['Follow','What the evidence means'],['Stop','No new argument']])},
 {skill:'clear',say:'Writing is clear and coherent when it fits the task, the purpose and the audience. For an argument, the task is to persuade, the purpose is to win agreement, and the audience decides the tone. Each sentence should serve the claim, with precise words, clear pronouns and no padding that hides the point.',pic:board('Task, purpose, audience',['Task: write an argument','Purpose: persuade the school board','Audience: adults who vote on policy','Choice: formal, clear, no padding'],['what is asked','what the writing must do','who reads it','how the writing sounds'])},
 {skill:'revise',say:'Good writers plan, draft, revise, edit and share. Planning lists the claim, reasons and evidence. Revising changes ideas and order: add evidence, answer a counterclaim, move a paragraph. Editing then corrects conventions such as spelling and punctuation. Doing them in this order keeps you from polishing a sentence that you later cut.',pic:flow('The writing process',[['Plan','Claim, reasons, evidence'],['Revise','Content and order'],['Edit','Spelling and commas']])},
 {skill:'parallel',say:'Parallel structure means that items doing the same job have the same grammatical form. In a list, match all the verbs, all the -ing words or all the to phrases. Pairs joined by not only and but also must match too. Parallelism makes a list easy to follow and gives an argument rhythm.',pic:board('Parallel structure',['Not parallel: “She likes hiking, to swim and biking.”','Parallel: “She likes hiking, swimming and biking.”','Match: -ing with -ing, to with to','Check pairs: not only X but also Y'],['mixed forms','all -ing forms','keep one pattern','matching pairs'])},
 {skill:'semi',say:'A comma splice joins two independent clauses with only a comma. Repair it with a semicolon, a period, or a comma plus and, but or so. A semicolon links closely related clauses. Before a conjunctive adverb such as however, the semicolon comes first and a comma follows.',pic:board('Comma splice repairs',['Splice: “The rain stopped, we went out.”','Fix 1: The rain stopped; we went out.','Fix 2: The rain stopped, and we went out.','Check: are both sides complete clauses?'],['comma alone','semicolon','comma plus conjunction','the test']),
  check:{prompt:tryIt(TRY[2]),answer:'A',options:['A','B','C'],hint:'Both halves are complete clauses. Which choice joins them with a semicolon only?',pic:pass('Fictional sentence',['The bus was late, the bell had already rung.'],false)}},
 {skill:'semi',say:'A colon comes after a complete clause and introduces a list, a quotation or an explanation. Do not put a colon right after a verb such as needs or include, since the clause is not yet complete. Semicolons can also separate list items that already contain commas, so each item stays clear.',pic:tab('Semicolon and colon jobs',[['semicolon','joins two related main clauses'],['; however,','semicolon before, comma after'],['colon','follows a complete clause, then a list or quotation'],['; in a long list','separates items that contain commas']],['Job'])},
 {skill:'revise',summary:true,say:'Tie the unit together with one habit: build, then check. Make a precise claim, support each reason with matched evidence, answer the opposing view, link the sections and end with a conclusion that follows. Then revise the content, keep the tone formal, and edit parallel structure, semicolons and colons.',pic:flow('Argument writing: the habit',[['Claim it','Precise and arguable'],['Prove it','Reasons, evidence, rebuttal'],['Polish it','Tone, transitions, punctuation']])}],
progression:{requires:['language-h-english-9-reading-informational-texts'],operations:2,demand:'Write a fair argument: choose a precise claim, match evidence to reasons, answer the opposing view, use transitions, keep a formal tone, end with a conclusion that follows, and revise and edit with parallel structure, semicolons and colons.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 ROWS.forEach(([skill,key,q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  if(!key){put(skill,`${q} ${c.text}. ${ask(c.n)}`,c.letter,null/* 25 Oct: no picture; it only repeated the question in tiny type */,why,[right,dot(right)]);return;}
  const [src,lines]=P(key),text=lines.join(' ');
  put(skill,`${src}: “${text}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);});
}};
